package pe.vichaval.gestionriego.finanzas.service;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.vichaval.gestionriego.agricultor.repository.AgricultorRepository;import pe.vichaval.gestionriego.finanzas.dto.*;import pe.vichaval.gestionriego.finanzas.entity.*;import pe.vichaval.gestionriego.finanzas.repository.*;import pe.vichaval.gestionriego.tesoreria.dto.PagoForm;import pe.vichaval.gestionriego.tesoreria.service.PagoService;
@Service@Transactional public class FinanzasService{private final CuentaCobrarRepository cuentas;private final ConceptoCobroRepository conceptos;private final AgricultorRepository agricultores;private final PagoService pagos;public FinanzasService(CuentaCobrarRepository c,ConceptoCobroRepository co,AgricultorRepository a,PagoService p){cuentas=c;conceptos=co;agricultores=a;pagos=p;}public List<CuentaCobrar>listar(){var lista=cuentas.findAll();lista.forEach(CuentaCobrar::actualizarVencida);return lista;}public CuentaCobrar get(Long id){return cuentas.findById(id).orElseThrow(()->new IllegalArgumentException("Cuenta no encontrada"));}public void crearCuenta(CuentaCobrarForm f){if(f.getFechaVencimiento().isBefore(f.getFechaEmision()))throw new IllegalArgumentException("El vencimiento no puede ser anterior a la emisión");var a=agricultores.findById(f.getAgricultorId()).orElseThrow();var c=conceptos.findById(f.getConceptoId()).orElseThrow();cuentas.save(new CuentaCobrar("CC-%06d".formatted(cuentas.count()+1),f,a,c));}public void registrarPago(Long cuentaId,PagoCuentaForm f){var c=get(cuentaId);if("ANULADA".equals(c.getEstado())||"PAGADA".equals(c.getEstado()))throw new IllegalStateException("La cuenta no admite pagos");c.aplicarPago(f.getMonto());PagoForm p=new PagoForm();p.setAgricultorId(c.getAgricultor().getId());p.setMonto(f.getMonto());p.setFecha(f.getFecha());p.setConcepto(c.getConcepto().getNombre()+" - "+c.getCodigo());p.setComprobante(f.getComprobante());p.setMetodo(f.getMetodo());pagos.registrar(p);}public void anular(Long id,String motivo){get(id).anular(motivo);}public List<ConceptoCobro>listarConceptos(){return conceptos.findAllByOrderByNombre();}public List<ConceptoCobro>conceptosActivos(){return conceptos.findByActivoTrueOrderByNombre();}public void crearConcepto(ConceptoCobroForm f){if(conceptos.existsByCodigoIgnoreCase(f.getCodigo()))throw new IllegalArgumentException("Código duplicado");conceptos.save(new ConceptoCobro(f));}}
